-- Full-text search index across all searchable entities.
-- These FTS5 virtual tables and their triggers are NOT represented in
-- schema.ts and will not be regenerated by `drizzle-kit generate` — they
-- must be maintained by hand. See note in schema.ts.

CREATE VIRTUAL TABLE `collections_fts` USING fts5(
  plex_rating_key UNINDEXED,
  title,
  summary,
  labels,
  section_title,
  tokenize = 'unicode61 remove_diacritics 2'
);
--> statement-breakpoint
INSERT INTO `collections_fts` (plex_rating_key, title, summary, labels, section_title)
  SELECT plex_rating_key, title, summary, COALESCE(labels, ''), section_title FROM `collections`;
--> statement-breakpoint
CREATE TRIGGER `collections_ai` AFTER INSERT ON `collections` BEGIN
  INSERT INTO `collections_fts` (plex_rating_key, title, summary, labels, section_title)
  VALUES (new.plex_rating_key, new.title, new.summary, COALESCE(new.labels, ''), new.section_title);
END;
--> statement-breakpoint
CREATE TRIGGER `collections_ad` AFTER DELETE ON `collections` BEGIN
  DELETE FROM `collections_fts` WHERE plex_rating_key = old.plex_rating_key;
END;
--> statement-breakpoint
CREATE TRIGGER `collections_au` AFTER UPDATE ON `collections` BEGIN
  DELETE FROM `collections_fts` WHERE plex_rating_key = old.plex_rating_key;
  INSERT INTO `collections_fts` (plex_rating_key, title, summary, labels, section_title)
  VALUES (new.plex_rating_key, new.title, new.summary, COALESCE(new.labels, ''), new.section_title);
END;
--> statement-breakpoint

